package main

import (
	"fmt"
	"strings"
)

func WordCount(s string) map[string]int {
	words := strings.Fields(s)
	count := make(map[string]int)

	for _, w := range words {
		count[w]++
	}
	return count
}

func main() {
	text := "go go go lang lang"
	fmt.Println(WordCount(text))
}

